import{z as o,x as s,o as r,c as p,q as n,j as t,D as E,d as B,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Abreu–Brunnermeier 同步失败","description":"","frontmatter":{"title":"Abreu–Brunnermeier 同步失败","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/abreu-brunnermeier.md","filePath":"econ/abreu-brunnermeier.md","lastUpdated":1791063341000}'),u={name:"econ/abreu-brunnermeier.md"};function d(m,e,b,C,D,f){const A=s("Mermaid");return r(),p("div",null,[e[2]||(e[2]=n('<h1 id="abreu–brunnermeier-同步失败" tabindex="-1">Abreu–Brunnermeier 同步失败 <a class="header-anchor" href="#abreu–brunnermeier-同步失败" aria-label="Permalink to &quot;Abreu–Brunnermeier 同步失败&quot;">​</a></h1><div class="epigraph"><p>套利者陆续知道泡沫存在，但不知道别人是不是已经知道；先动手的人独自承担价格还在涨的风险，于是都等，泡沫比消息更长寿。</p><footer>—— Abreu and Brunnermeier, Bubbles and Crashes, Econometrica 2003</footer></div><p><a href="/econ/rational-bubbles">上一课</a>留下「人人知道仍可能持有」。本课缺口是时机：专业套利者<strong>陆续</strong>意识到错定价，攻击需要同步。没有共同知识的那一天，各自动手都太早。不重写 \\(B=E[mB&#39;]\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Abreu 与 Brunnermeier（2003）：泡沫在某个未观测时点开始，套利者按随机顺序得到信号，知道「已经开始」但不知道自己在序列中的位置。卖空有资本约束（每人只能抛有限量），必须凑够数量才能刺破。每个人都想骑泡沫到接近破裂再动手（preemption 与 waiting 的权衡）。均衡是延迟：从第一个信号到崩盘有一段内生时间。缺口是给 <a href="/econ/limits-to-arbitrage">SV 套利限制</a>加上<strong>信息同步</strong>，而不是再写委托赎回。</p><p><span class="marginnote">共同知识比「人人知道」更强：人人知道人人知道……。泡沫可以在高阶信念缺口上存活。这是协调博弈，不是噪声交易者的随机需求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>连续时间，信号到达的泊松或均匀顺序，资本加总阈值。策略：收到信号后等待 \\(\\tau\\) 再攻击。对称均衡 \\(\\tau\\gt 0\\)。比较静态：资本越分散、信号越不同步，延迟越长，泡沫越大。崩盘可以比基本面消息猛——因为同步一旦达成，资本同时到位。</p>',8)),(r(),t(l,null,{default:E(()=>[i(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E4%BF%A1%E5%8F%B7%E9%99%86%E7%BB%AD%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20CK%5B%22%E6%B2%A1%E6%9C%89%E5%85%B1%E5%90%8C%E7%9F%A5%E8%AF%86%E7%9A%84%E6%97%B6%E7%82%B9%22%5D%0A%20%20CK%20--%3E%20WAIT%5B%22%E6%80%95%E8%87%AA%E5%B7%B1%E5%8A%A8%E6%89%8B%E5%A4%AA%E6%97%A9%22%5D%0A%20%20WAIT%20--%3E%20DEL%5B%22%E5%9D%87%E8%A1%A1%E5%BB%B6%E8%BF%9F%3A%20%E6%B3%A1%E6%B2%AB%E8%B6%85%E5%AF%BF%22%5D%0A%20%20DEL%20--%3E%20CRASH%5B%22%E9%98%88%E5%80%BC%E5%87%91%E9%BD%90%3A%20%E5%B4%A9%E7%9B%98%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[B(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"不把「攻击」写成限价簿上的大单扫货。阈值是资本加总，协议仍属量化栏。",-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"机制是协调失败。骑泡沫的收益是继续上涨；过早攻击的成本是被轧空或错过上涨。SV 的赎回在此换成「别人还没动手时价格继续涨」。DSSW 的噪声仍可以提供上涨；AB 即使在泡沫终将破裂的共同信念下，也能因不同步而延迟。与理性泡沫的差别：AB 的价格路径由行为或外生泡沫过程驱动，理论核心是刺破的博弈，不是齐次欧拉。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：preemption（抢跑）担心的是「我按了卖出键、别人还没按」。此时价格还在涨，你的空单先亏钱，可能被强制平仓（被轧空）。就像约好一起翻桌，你先动手，桌子没翻，你自己先摔了——所以每个人都不愿做第一个。")],-1)),e[7]||(e[7]=a("p",null,"「人人知道价格太高」还不是共同知识：我不知道你是不是已经收到信号。先动手且别人未动，价格继续涨，自己被轧。对称均衡是等待一段内生时间。资本分散、信号不同步，则延迟拉长。不把攻击写成簿上的扫货；阈值是资本加总。主干在交接处停，本课仍是均衡时机，不是协议。",-1)),(r(),t(l,null,{default:E(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%94%B6%E5%88%B0%E4%BF%A1%E5%8F%B7%3A%20%E6%B3%A1%E6%B2%AB%E5%B7%B2%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20Q%5B%22%E7%8E%B0%E5%9C%A8%E6%94%BB%E5%87%BB%E8%BF%98%E6%98%AF%E7%BB%A7%E7%BB%AD%E7%AD%89%22%5D%0A%20%20Q%20--%3E%7C%22%E7%8B%AC%E8%87%AA%E6%97%A9%E5%8A%A8%22%7C%20EARLY%5B%22%E4%BB%B7%E6%A0%BC%E4%BB%8D%E6%B6%A8%3A%20%E8%A2%AB%E8%BD%A7%E7%A9%BA%E8%80%8C%E4%BA%8F%E6%8D%9F%22%5D%0A%20%20Q%20--%3E%7C%22%E9%9A%8F%E5%A4%A7%E6%B5%81%E6%99%9A%E5%8A%A8%22%7C%20MISS%5B%22%E6%B3%A1%E6%B2%AB%E5%B7%B2%E8%A2%AB%E5%88%AB%E4%BA%BA%E5%88%BA%E7%A0%B4%3A%20%E6%97%A0%E5%88%A9%E5%8F%AF%E5%9B%BE%22%5D%0A%20%20Q%20--%3E%7C%22%E7%AD%89%20tau%20%E5%90%8E%E5%90%8C%E6%AD%A5%E6%94%BB%E5%87%BB%22%7C%20EQ%5B%22%E5%9D%87%E8%A1%A1%3A%20%E9%98%88%E5%80%BC%E5%90%8C%E6%97%B6%E5%87%91%E9%BD%90%2C%20%E5%B4%A9%E7%9B%98%22%5D%0A%20%20EQ%20--%3E%20CS%5B%22%E8%B5%84%E6%9C%AC%E8%B6%8A%E5%88%86%E6%95%A3%2C%20%E4%BF%A1%E5%8F%B7%E8%B6%8A%E4%B8%8D%E5%90%8C%E6%AD%A5%2C%20%E5%BB%B6%E8%BF%9F%E8%B6%8A%E9%95%BF%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[B(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=n('<p><span class="marginnote">直觉类比：这像一局击鼓传花——花停之前谁都想多拿一会儿，但谁也不想在音乐停止时还攥着花。AB 的贡献是证明：即使所有人都知道花迟早要停，只要「停的时机」不是共同知识，传递就会比常识预期的更久。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>若信号是公共公告（人人同时知道），同步问题消失，模型退回谁先抢的简单抢先。完全无卖空约束则一人即可刺破。本课不估计延迟长度。金融危机叙事可以当动机，不是识别。</p><p><span class="marginnote">常见误区：初学者容易以为崩盘一定由坏消息触发。AB 的模型里崩盘可以没有任何基本面新闻——只是等待结束、资本同时到位。看到「消息面平静却暴跌」，不一定是市场非理性，可能只是同步终于达成了。</span></p><p>后课默认：羊群与信息级联是另一条「看见别人的行动当信号」的协调；AB 是已经知情的人等别人一起动手。</p><p>陆续知情加资本阈值，均衡是等待：泡沫比第一条消息更长寿，崩盘是同步成功。</p><p>人人知道还不是共同知识。SV 是资本逃走；AB 是资本到了仍不下手。</p><p><span class="marginnote">公共同时公告则同步问题消失；一人可刺破则延迟消失。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>陆续知情 + 资本阈值 ⇒ 均衡等待，泡沫超寿。</li><li>崩盘是同步成功，不是基本面突然跳。</li><li>在 SV 的融资限制之上加上高阶信念缺口。</li><li>公共同时公告则同步问题消失。</li><li>一人即可刺破则延迟消失。</li><li>出处：Abreu and Brunnermeier, <em>Econometrica</em> 2003。</li></ul>',10))])}const F=o(u,[["render",d]]);export{c as __pageData,F as default};
